using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Collections.Generic;
namespace Caronte.EditorTools{
public static class WorkcellSetup{
 const string V2="Assets/AssetHendrix/Models/BrazoRobot2/";
 const string Laser="Assets/AssetHendrix/Models/Robot láser/";
 public static Material MakeMaterial(bool laser){
 string folder=laser?Laser:V2,prefix=folder+(laser?"industrial_laser_3d_model_":"industrial_robot_arm_3d_model_v02_");
 var normalImporter=AssetImporter.GetAtPath(prefix+"normal.jpg") as TextureImporter;if(normalImporter&&normalImporter.textureType!=TextureImporterType.NormalMap){normalImporter.textureType=TextureImporterType.NormalMap;normalImporter.SaveAndReimport();}
 string packedPath=folder+"MetallicSmoothness.png";
 if(!System.IO.File.Exists(packedPath)){var metal=new Texture2D(2,2);metal.LoadImage(System.IO.File.ReadAllBytes(prefix+"metallic.jpg"));var rough=new Texture2D(2,2);rough.LoadImage(System.IO.File.ReadAllBytes(prefix+"roughness.jpg"));var packed=new Texture2D(metal.width,metal.height,TextureFormat.RGBA32,true,true);var pixels=new Color[metal.width*metal.height];var m=metal.GetPixels32();for(int y=0;y<metal.height;y++)for(int x=0;x<metal.width;x++){float red=m[y*metal.width+x].r/255f;pixels[y*metal.width+x]=new Color(red,red,red,1-rough.GetPixelBilinear(x/(float)(metal.width-1),y/(float)(metal.height-1)).r);}packed.SetPixels(pixels);packed.Apply();System.IO.File.WriteAllBytes(packedPath,packed.EncodeToPNG());Object.DestroyImmediate(metal);Object.DestroyImmediate(rough);Object.DestroyImmediate(packed);AssetDatabase.ImportAsset(packedPath);var imp=AssetImporter.GetAtPath(packedPath) as TextureImporter;imp.sRGBTexture=false;imp.alphaSource=TextureImporterAlphaSource.FromInput;imp.SaveAndReimport();}
 string path=folder+(laser?"RobotLaser.mat":"BrazoRobot2.mat");var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(!material){material=new Material(Shader.Find("AssetHendrix/Industrial Robot PBR"));AssetDatabase.CreateAsset(material,path);}material.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(prefix+"basecolor.jpg"));material.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(prefix+"normal.jpg"));material.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(packedPath));material.SetFloat("_Metallic",.8f);material.SetFloat("_Smoothness",.65f);material.SetFloat("_BumpScale",.8f);EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();return material;
 }
 static Transform Pivot(string name,Transform parent,Vector3 point){var t=new GameObject(name).transform;t.SetParent(parent,false);t.position=point;t.rotation=Quaternion.identity;return t;}
 static Vector3 P(Transform model,float x,float y,float z){return model.TransformPoint(new Vector3(x,-z,y));}
 static Transform Import(string path,Transform root,float scale){var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),root);PrefabUtility.UnpackPrefabInstance(model,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);model.transform.localPosition=Vector3.zero;model.transform.localScale=Vector3.one*scale;var renderers=model.GetComponentsInChildren<Renderer>();Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);root.position+=Vector3.up*(.05f-bounds.min.y);return model.transform;}
 static void Material(Transform root,Material material){foreach(var r in root.GetComponentsInChildren<Renderer>())r.sharedMaterial=material;}
 static IndustrialRobotArm Arm(CaronteStation s,int index,Material material){
 var root=new GameObject(index==0?"RobotV2_Left":"RobotV2_Right").transform;root.SetParent(s.transform,false);root.position=new Vector3(index==0?-2.2f:2.2f,0,8);if(index==1)root.rotation=Quaternion.Euler(0,180,0);
 var model=Import(V2+"industrial robot arm 3d model v02.fbx",root,4.2f);Material(model,material);
 Vector3 shoulderPoint=P(model,.09f,.30f,.11f),elbowPoint=P(model,.08f,.81f,-.26f),wristPoint=P(model,.03f,.82f,.24f),gripPoint=P(model,0,.53f,.49f);
 var yaw=Pivot("BaseYaw",root,new Vector3(shoulderPoint.x,.4f,shoulderPoint.z));var shoulder=Pivot("ShoulderPivot",yaw,shoulderPoint);var elbow=Pivot("ElbowPivot",shoulder,elbowPoint);var wrist=Pivot("WristPivot",elbow,wristPoint);var grip=Pivot("GripSocket",wrist,gripPoint);
 var first=Pivot("JawA",wrist,P(model,-.04f,.635f,.445f));var second=Pivot("JawB",wrist,P(model,.04f,.635f,.445f));
 var parts=new List<Transform>();foreach(Transform t in model)parts.Add(t);
 foreach(var part in parts){Transform parent=root;switch(part.name){case "brazo_1":case "Cable_5":case "Cable_8":parent=shoulder;break;case "base_brazo":case "Brazo_2":case "Cable":case "Cable_2":case "Cable_4":parent=elbow;break;case "Base_Pinza":case "base_pinza2":case "Cable_3":case "Mano_1":parent=wrist;break;case "Mano_5":case "Mano_4":parent=first;break;case "Mano_2":case "Mano_3":parent=second;break;}part.SetParent(parent,true);}
 Object.DestroyImmediate(model.gameObject);var arm=root.gameObject.AddComponent<IndustrialRobotArm>();arm.robotIndex=index;arm.baseYaw=yaw;arm.shoulder=shoulder;arm.elbow=elbow;arm.wrist=wrist;arm.gripSocket=grip;arm.leftJaw=first.position.x<second.position.x?first:second;arm.rightJaw=first.position.x<second.position.x?second:first;arm.Calibrate();arm.SetGripPose(1);arm.MoveTo(yaw.position+Vector3.up*1.9f+Vector3.back*.3f);return arm;
 }
 static RobotLaserWelder LaserRobot(CaronteStation s,Material material){
 var root=new GameObject("LaserRobot_Rear").transform;root.SetParent(s.transform,false);root.position=new Vector3(0,0,11.8f);var model=Import(Laser+"laser 3d model v02.fbx",root,4.0f);Material(model,material);var laser=model.Find("Laser");var bounds=laser.GetComponent<Renderer>().bounds;var head=Pivot("LaserHeadPivot",root,new Vector3(bounds.min.x,bounds.center.y,bounds.center.z));var nozzle=Pivot("LaserNozzle",head,new Vector3(bounds.max.x,bounds.center.y,bounds.center.z));foreach(var name in new[]{"Laser","Base_1","tripo_part_6","tripo_part_45","tripo_part_131"}){var t=model.Find(name);if(t)t.SetParent(head,true);}
 var welder=root.gameObject.AddComponent<RobotLaserWelder>();welder.head=head;welder.nozzle=nozzle;welder.effects=s.GetComponent<StationPolish>();welder.room=s.GetComponent<StationRoomController>();string path=Laser+"LaserBeam.mat";var beam=AssetDatabase.LoadAssetAtPath<Material>(path);if(!beam){beam=new Material(Shader.Find("Universal Render Pipeline/Unlit"));AssetDatabase.CreateAsset(beam,path);}beam.SetColor("_BaseColor",new Color(6,.03f,.01f,1));beam.SetFloat("_Surface",1);beam.SetFloat("_SrcBlend",1);beam.SetFloat("_DstBlend",1);beam.SetFloat("_ZWrite",0);beam.SetFloat("_Cull",0);beam.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");beam.renderQueue=3100;welder.beamMaterial=beam;head.rotation=Quaternion.FromToRotation((nozzle.position-head.position).normalized,(s.assemblyOrigin.position-head.position).normalized)*head.rotation;return welder;
 }
 public static void Build(){
 var s=Object.FindFirstObjectByType<CaronteStation>();if(s.transform.Find("RobotV2_Left"))return;
 if(s.importedRobotArm)s.importedRobotArm.gameObject.SetActive(false);foreach(var group in new[]{s.armBases,s.armUpper,s.armLower,s.armElbow,s.armWrist,s.armGrip})foreach(var old in group)if(old)old.gameObject.SetActive(false);
 var mat=AssetDatabase.LoadAssetAtPath<Material>(V2+"BrazoRobot2.mat");var laserMat=AssetDatabase.LoadAssetAtPath<Material>(Laser+"RobotLaser.mat");s.articulatedArms=new[]{Arm(s,0,mat),Arm(s,1,mat)};s.importedRobotArm=s.articulatedArms[0];
 for(int i=0;i<2;i++){var a=s.articulatedArms[i];s.armBases[i]=a.baseYaw;s.armUpper[i]=a.shoulder;s.armLower[i]=a.elbow;s.armElbow[i]=a.elbow;s.armWrist[i]=a.wrist;s.armGrip[i]=a.gripSocket;}
 s.laserWelder=LaserRobot(s,laserMat);
 foreach(Transform t in s.transform){if(t.name=="SupplyBench"){float sign=t.position.x<0?-1:1;t.position=new Vector3(sign*3.2f,1.07f,5);t.localScale=new Vector3(1.5f,.16f,1.6f);}if(t.name=="SupplySupport"){float sign=t.position.x<0?-1:1;t.position=new Vector3(sign*3.2f,.55f,5);t.localScale=new Vector3(.75f,1.1f,1.1f);}}
 s.leftSupply.position=new Vector3(-3.2f,1.2f,4.5f);s.rightSupply.position=new Vector3(3.2f,1.2f,4.5f);
 var bay=s.transform.Find("AssemblyBay");var pedestal=bay.Find("AssemblyPedestal");pedestal.localScale=new Vector3(2,.65f,2);var top=bay.Find("AssemblyTop");top.localScale=new Vector3(2.1f,.05f,2.1f);
 var floor=s.transform.Find("Floor");floor.position=new Vector3(0,-.15f,5);floor.localScale=new Vector3(12,.3f,20);var ceiling=s.transform.Find("Ceiling");ceiling.position=new Vector3(0,6,5);ceiling.localScale=new Vector3(12,.3f,20);s.transform.Find("RearBulkhead").position=new Vector3(0,3,15);var side=s.transform.Find("RightBulkhead");side.position=new Vector3(6,3,5);side.localScale=new Vector3(.3f,6,20);
 foreach(string name in new[]{"WindowSafetyCollider","WindowLowerFrame","WindowUpperFrame"}){var t=s.transform.Find(name);var p=t.position;p.z=5;t.position=p;var scale=t.localScale;scale.z=20;t.localScale=scale;}
 var sample=s.transform.Find("FloorPanel");for(int x=-5;x<=5;x+=2)for(int z=11;z<=13;z+=2){var tile=Object.Instantiate(sample.gameObject,s.transform);tile.name="FloorExtension_"+x+"_"+z;tile.transform.position=new Vector3(x,.01f,z);}
 for(int z=11;z<=14;z+=3){var source=s.transform.Find("WindowMullion");var t=Object.Instantiate(source.gameObject,s.transform).transform;t.name="WindowMullionExtension_"+z;t.position=new Vector3(-6,3,z);}
 SavePrefabs(s);EditorSceneManager.MarkSceneDirty(s.gameObject.scene);EditorSceneManager.SaveScene(s.gameObject.scene);AssetDatabase.SaveAssets();
 }
 static void SavePrefabs(CaronteStation s){foreach(var a in s.articulatedArms){var copy=Object.Instantiate(a.gameObject);copy.transform.position=Vector3.zero;copy.transform.rotation=Quaternion.identity;PrefabUtility.SaveAsPrefabAsset(copy,V2+(a.robotIndex==0?"BrazoV2_Izquierdo.prefab":"BrazoV2_Derecho.prefab"));Object.DestroyImmediate(copy);}}
 public static void BindAudio(){
 var d=Object.FindFirstObjectByType<MissionControlDirector>();string root="Assets/AssetsMaximo/Audios/";
 d.tutorialRecordings=new AudioClip[6];d.missionRecordings=new AudioClip[6];for(int i=0;i<6;i++)d.tutorialRecordings[i]=AssetDatabase.LoadAssetAtPath<AudioClip>(root+"Mision 1/MISION 1 Parte "+(i+1)+".mp3");for(int i=1;i<6;i++)d.missionRecordings[i]=AssetDatabase.LoadAssetAtPath<AudioClip>(root+"MISION "+(i+1)+".mp3");
 d.voiceClips=new AudioClip[52];string sub=root+"Mensajes Individuales/";string[] names={"## Lanzamiento — Todas las misiones","## Inserción orbital y búsqueda de señal","## Éxito de las siguientes misiones","## Derrota por fallo de la misión (GENERAL)","## Final de la campaña"};for(int i=0;i<5;i++)d.voiceClips[24+i]=AssetDatabase.LoadAssetAtPath<AudioClip>(sub+names[i]+".mp3");d.voiceClips[48]=AssetDatabase.LoadAssetAtPath<AudioClip>(sub+"## Finalización del tutorial.mp3");d.voiceClips[49]=AssetDatabase.LoadAssetAtPath<AudioClip>(sub+"## Mensaje decodificado.mp3");d.voiceClips[50]=AssetDatabase.LoadAssetAtPath<AudioClip>(sub+"## Derrota por vencimiento del plazo.mp3");d.voiceClips[51]=AssetDatabase.LoadAssetAtPath<AudioClip>(sub+"## Alerta final de la estación.mp3");d.tutorialCompleteVoice=d.voiceClips[48];d.destructionWarningSeconds=40;EditorUtility.SetDirty(d);EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);AssetDatabase.SaveAssets();
 }
}
